Node* find_closest_node(const Graph& graph, float x, float y) {
    // Iterate over all nodes in the graph
    for (const auto& node : graph.getNodes()) {
        // Calculate the distance between the current node and the given coordinates
        float distance = std::sqrt(std::pow(node.getX() - x, 2) + std::pow(node.getY() - y, 2));
        // If this is the first node or the distance is smaller than the previous smallest distance, update the closest node
        if (!closestNode || distance < smallestDistance) {
            closestNode = &node;
            smallestDistance = distance;
        }
    }
    return closestNode;
}

